      const list = [];
      while (list.length < cards2.length) {
        const card = get.cardPile((cardx) => !suits.includes(get.suit(cardx)) && !list.includes(cardx));
        if (card) {
          list.push(card);
        } else {
          break;
        }
      }
      if (list.length) {
        await player.gain({
          cards: list,
          animate: "gain2"
        });
      }
