      aiValue(player, card, num) {
        if (get.name(card) != "shan" && get.itemtype(card) == "card" && (!card.hasGaintag("olchongshen") || get.color(card) != "red")) {
          return;
        }
        let cards2 = player.getCards("hs", (card2) => get.name(card2) == "shan" || card2.hasGaintag("olchongshen"));
        cards2.sort((a, b) => (get.name(b) == "shan" ? 1 : 2) - (get.name(a) == "shan" ? 1 : 2));
        const geti = () => {
          if (cards2.includes(card)) {
            return cards2.indexOf(card);
          }
          return cards2.length;
        };
        if (get.name(card) == "shan") {
          return Math.min(num, [6, 4, 3][Math.min(geti(), 2)]) * 0.6;
        }
        return Math.max(num, [6.5, 4, 3][Math.min(geti(), 2)]);
      },
      aiUseful() {
        return lib.skill.olchongshen.mod.aiValue.apply(this, arguments);
      }
