  olgongjie: {
    audio: 2,
    trigger: { global: "phaseBegin" },
    filter(event, player) {
      if (!player.countCards("he")) {
        return false;
      }
      let history = player.actionHistory, isRound = false;
      history.forEach((evt, index) => {
        if (evt.isRound) {
          isRound = index;
        }
      });
      if (isRound === false) {
        return false;
      }
      for (let num = 0; num < history.length - 1; num++) {
        if (num < isRound || history[num].isSkipped) {
          continue;
        }
        return num == history.length - 1;
      }
      return true;
    },
    direct: true,
    async content(event, trigger, player) {
      var num = player.countCards("he"), draws = [];
      var { bool, targets } = await player.chooseTarget(get.prompt2("olgongjie"), [1, num], lib.filter.notMe).set("ai", (target2) => get.attitude(_status.event.player, target2)).forResult();
      if (!bool) {
        return;
      }
      targets = targets.sortBySeat();
      player.logSkill("olgongjie", targets);
      for (var target of targets) {
        var { bool, cards: cards2 } = await target.gainPlayerCard(player, true, "he").forResult();
        if (bool) {
          draws.add(get.suit(cards2[0], player));
        }
      }
      player.draw(draws.length);
    }
  },
