  //曹宪曹华
  huamu: {
    audio: 6,
    trigger: { player: "useCardAfter" },
    locked: false,
    filter(event, player) {
      if (!player.hasHistory("lose", function(evt) {
        const evtx = evt.relatedEvent || evt.getParent();
        return evt.hs.length > 0 && evtx == event;
      }) || !event.cards.filterInD("oe").length) {
        return false;
      }
      var history = game.getGlobalHistory("useCard");
      var index = history.indexOf(event);
      if (index < 1) {
        return false;
      }
      return get.color(event.card) != get.color(history[index - 1].card);
    },
    prompt2: (event) => "将" + get.translation(event.cards.filterInD("oe")) + "置于武将牌上",
    check(event, player) {
      if (!game.hasPlayer(function(current) {
        return current.hasSkill("qianmeng", null, null, false) && get.attitude(player, current) > 0;
      })) {
        return false;
      }
      var cards2 = event.cards.filterInD("e");
      if (!cards2.length) {
        return true;
      }
      var card = cards2[0];
      if (get.owner(card) == player) {
        if (get.value(card, player) <= 0) {
          return true;
        }
        var subtype = get.subtype(card);
        if (player.hasCard("hs", function(card2) {
          return get.subtype(card2) == subtype && player.canUse(card2, player) && get.effect(player, card2, player, player) > 0;
        })) {
          return true;
        }
      }
      return false;
    },
    async content(event, trigger, player) {
      const cards2 = trigger.cards.filterInD("oe");
      player.addToExpansion({ cards: cards2, animate: "gain2", gaintag: ["huamu"] });
    },
    ai: {
      reverseOrder: true,
      combo: "qianmeng"
    },
    mod: {
      aiOrder(player, card, num) {
        if (typeof card == "object") {
          var history = game.getGlobalHistory("useCard");
          if (!history.length) {
            return;
          }
          var evt = history[history.length - 1];
          if (evt && evt.card && get.color(evt.card) != get.color(card)) {
            return num + 4;
          }
        }
      }
    },
    marktext: "木",
    intro: {
      name: "灵杉&玉树",
      markcount(storage, player) {
        var red = [], black = [];
        var cards2 = player.getExpansions("huamu");
        for (var i of cards2) {
          var color = get.color(i, false);
          (color == "red" ? red : black).push(i);
        }
        return "" + black.length + "/" + red.length;
      },
      content: "expansion",
      mark(dialog, storage, player) {
        var red = [], black = [];
        var cards2 = player.getExpansions("huamu");
        for (var i of cards2) {
          var color = get.color(i, false);
          (color == "red" ? red : black).push(i);
        }
        if (black.length) {
          dialog.addText("灵杉");
          dialog.addSmall(black);
        }
        if (red.length) {
          dialog.addText("玉树");
          dialog.addSmall(red);
        }
      }
    }
  },
