  oljuanxia: {
    audio: 2,
    trigger: { player: "phaseJieshuBegin" },
    direct: true,
    async content(event, trigger, player) {
      const result = await player.chooseTarget(get.prompt2("oljuanxia"), lib.filter.notMe).set("ai", function(target) {
        const player2 = _status.event.player, list2 = [];
        for (const name of lib.inpile) {
          const info = lib.card[name];
          if (!info || info.type != "trick" || info.notarget || info.selectTarget && info.selectTarget != 1) {
            continue;
          }
          if (!player2.canUse(name, target, false)) {
            continue;
          }
          const eff = get.effect(target, { name }, player2, player2);
          if (eff > 0) {
            list2.push(eff);
          }
        }
        list2.sort().reverse();
        if (!list2.length) {
          return 0;
        }
        return list2[0] + (list2[1] || 0) + (list2[2] || 0);
      }).forResult();
      if (result.bool) {
        const target = result.targets[0];
        event.target = target;
        player.logSkill("oljuanxia", target);
      } else {
        event.finish();
        return;
      }
      let list = [];
      for (const name of lib.inpile) {
        const info = lib.card[name];
        if (!info || info.type != "trick" || info.notarget || info.selectTarget && info.selectTarget != 1) {
          continue;
        }
        list.push(name);
      }
      if (!list.length) {
        event.finish();
        return;
      } else {
        event.list = list;
        event.count = 0;
      }
      while (true) {
        list = event.list.filter(function(name) {
          return player.canUse(name, event.target, false);
        });
        if (list.length) {
          const next = player.chooseButton(["视为对" + get.translation(event.target) + "使用一张牌", [list, "vcard"]]).set("ai", function(button) {
            let evt = _status.event.getParent(), eff = get.effect(evt.target, { name: button.link[2] }, evt.player, evt.player);
            if (evt.target.hp < 2 || get.attitude(evt.player, evt.target) > 0 || evt.target.hp < 3 && get.tag(button.link, "damage")) {
              return eff;
            }
            return eff + get.effect(evt.player, { name: "sha" }, evt.target, evt.player);
          });
          if (event.count == 0) {
            next.set("forced", true);
          }
          const result2 = await next.forResult();
          if (result2.bool) {
            event.count++;
            const name = result2.links[0][2];
            event.list.remove(name);
            await player.useCard({ name, isCard: true }, event.target, false);
          } else {
            event.stopped = true;
          }
        } else {
          event.stopped = true;
        }
        if (event.target.isIn() && event.count > 0) {
          if (event.count < 3 && !event.stopped && event.list.length > 0) {
            continue;
          } else {
            event.target.addTempSkill("oljuanxia_counter", { player: "phaseAfter" });
            if (!event.target.storage.oljuanxia_counter) {
              event.target.storage.oljuanxia_counter = {};
            }
            if (!event.target.storage.oljuanxia_counter[player.playerid]) {
              event.target.storage.oljuanxia_counter[player.playerid] = 0;
            }
            event.target.storage.oljuanxia_counter[player.playerid] += event.count;
          }
        }
        break;
      }
    },
    subSkill: {
      counter: {
        trigger: { player: "phaseEnd" },
        forced: true,
        charlotte: true,
        onremove: true,
        filter(event, player) {
          var map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (var i in map2) {
            if (map1[i] && map1[i].isIn() && player.canUse("sha", map1[i], false)) {
              return true;
            }
          }
          return false;
        },
        logTarget(event, player) {
          var list = [];
          var map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (var i in map2) {
            if (map1[i] && map1[i].isIn()) {
              list.push(map1[i]);
            }
          }
          return list;
        },
        async content(event, trigger, player) {
          const list = [];
          const map1 = _status.connectMode ? lib.playerOL : game.playerMap, map2 = player.storage.oljuanxia_counter;
          if (!map2) {
            return false;
          }
          for (const i in map2) {
            if (map1[i] && map1[i].isIn()) {
              list.push(map1[i]);
            }
          }
          list.sortBySeat();
          event.num = 0;
          event.targets = list;
          let result = event._result;
          while (true) {
            const target = event.targets[event.num];
            event.target = target;
            if (target.isIn() && player.canUse("sha", target, false)) {
              const boolResult = await player.chooseBool("狷狭：是否视为对" + get.translation(target) + "依次使用" + get.cnNumber(player.storage.oljuanxia_counter[target.playerid]) + "张【杀】？").set("goon", get.effect(target, { name: "sha" }, player, player) > 0).set("ai", () => _status.event.goon).forResult();
              if (boolResult) {
                result = boolResult;
              }
            }
            event.num++;
            if (result.bool) {
              event.count = player.storage.oljuanxia_counter[target.playerid];
              while (true) {
                event.count--;
                if (target.isIn() && player.canUse("sha", target, false)) {
                  const useCardResult = await player.useCard({ name: "sha", isCard: true }, target, false).forResult();
                  if (useCardResult) {
                    result = useCardResult;
                  }
                }
                if (event.count > 0) {
                  continue;
                }
                break;
              }
              if (event.num < event.targets.length) {
                continue;
              }
              return;
            } else if (event.num < event.targets.length) {
              continue;
            } else {
              event.finish();
              return;
            }
          }
        }
      }
    }
  },
