  guanxu: {
    audio: 2,
    enable: "phaseUse",
    usable: 1,
    filter(event, player) {
      return game.hasPlayer((current) => lib.skill.guanxu.filterTarget(null, player, current));
    },
    filterTarget(card, player, target) {
      return target != player && target.countCards("h") > 0;
    },
    async content(event, trigger, player) {
      const { target } = event;
      const cards2 = get.cards(5, true);
      game.updateRoundNumber();
      let hs = target.getCards("h");
      const dialog = ["观虚：选择要操作的牌", '<div class="text center">' + get.translation(target) + "的手牌</div>", hs, '<div class="text center">牌堆顶</div>', cards2];
      const result = await player.chooseButton(dialog, 2).set("filterButton", function(button) {
        if (ui.selected.buttons.length) {
          return get.position(button.link) != get.position(ui.selected.buttons[0].link);
        }
        return true;
      }).set("cards1", hs).set("cards2", cards2).set("ai", function(button) {
        var card = button.link, cards1 = _status.event.cards1.slice(0);
        var cards22 = _status.event.cards2.slice(0), target2 = _status.event.getParent().target;
        if (!ui.selected.buttons.length) {
          if (!cards1.includes(card)) {
            return 0;
          }
          cards1.remove(card);
          var suits2 = cards22.map(function(i2) {
            return get.suit(i2, target2);
          });
          for (var i of lib.suit) {
            var num = cards1.filter(function(c) {
              return get.suit(c, target2) == i;
            }).length;
            if (num > 2 || num > 1 && suits2.includes(i)) {
              return 20 + get.value(card);
            }
          }
          return get.value(card);
        }
        cards1.remove(ui.selected.buttons[0].link);
        cards1.push(card);
        for (var i of lib.suit) {
          if (cards1.filter(function(c) {
            return get.suit(c, target2) == i;
          }).length > 2) {
            return 20 - get.value(card);
          }
          return get.value(ui.selected.buttons[0].link) - get.value(card);
        }
      }).forResult();
      if (result.bool) {
        const cards22 = result.links;
        if (get.position(cards22[0]) != "h") {
          cards22.reverse();
        }
        const next = target.lose(cards22[0], ui.cardPile);
        next.insert_index_card = cards22[1];
        next.insert_index = function(event2) {
          return event2.insert_index_card;
        };
        await next;
        await target.gain(cards22[1], "draw");
      } else {
        event.finish();
        return;
      }
      game.updateRoundNumber();
      const suits = [], map = {};
      hs = target.getCards("h");
      if (hs.length) {
        for (const i of hs) {
          if (!lib.filter.canBeDiscarded(i, player, target, "guanxu")) {
            continue;
          }
          const suit = get.suit(i, target);
          if (!map[suit]) {
            map[suit] = 1;
          } else {
            map[suit]++;
          }
          if (map[suit] > 2) {
            suits.add(suit);
          }
        }
        const next = player.discardPlayerCard(target, 3, "visible", "h");
        next.set("suits", suits);
        next.set("filterButton", function(button) {
          var suit = get.suit(button.link);
          if (!ui.selected.buttons.length) {
            return _status.event.suits.includes(suit);
          }
          return suit == get.suit(ui.selected.buttons[0].link);
        });
        if (suits.length) {
          next.set("forced", true);
        }
        await next;
      }
    },
    ai: {
      order: 9,
      result: {
        target(player, target) {
          if (target.countCards("h") > 3) {
            return -5;
          }
          if (target.countCards("h") == 3) {
            return -3;
          }
          return -0.5;
        }
      }
    }
  },
