  qianya: {
    audio: 2,
    trigger: { target: "useCardToTargeted" },
    filter(event, player) {
      return get.type(event.card, "trick") == "trick" && player.countCards("h");
    },
    async cost(event, trigger, player) {
      let nh = player.countCards("h");
      event.result = await player.chooseCardTarget({
        filterCard: true,
        filterTarget(card, player2, target) {
          return target != player2;
        },
        selectCard: [1, nh],
        allowChooseAll: true,
        ai1(card) {
          var player2 = _status.event.player;
          var cardname = _status.event.cardname;
          if (_status.event.du) {
            return -get.value(card, player2, "raw");
          } else if (_status.event.shuimeng) {
            if (cardname == "wuzhong") {
              if (player2.needsToDiscard(2, (i, player3) => {
                return !ui.selected.cards.includes(i) && !player3.canIgnoreHandcard(i);
              })) {
                return 10 - get.value(card, player2, "raw");
              }
            } else if (cardname == "guohe") {
              if (player2.needsToDiscard(-1, (i, player3) => {
                return !ui.selected.cards.includes(i) && !player3.canIgnoreHandcard(i);
              })) {
                return 10 - get.value(card, player2, "raw");
              }
            }
            return 0;
          } else if (cardname == "lebu") {
            if (player2.needsToDiscard(1, (i, player3) => {
              return !ui.selected.cards.includes(i) && !player3.canIgnoreHandcard(i);
            })) {
              return 8 - get.value(card, player2, "raw");
            } else {
              if (!ui.selected.cards.length) {
                return 6 - get.value(card, player2, "raw");
              }
              return 0;
            }
          } else if (cardname == "shunshou") {
            if (_status.event.nh <= 2) {
              return get.value(card, player2, "raw");
            }
          } else if (cardname == "huogong") {
            if (player2.hp == 1) {
              return get.value(card, player2, "raw");
            }
          }
          if (ui.selected.cards.length) {
            return 0;
          }
          return 7 - get.value(card, player2, "raw");
        },
        ai2(target) {
          var att = get.attitude(_status.event.player, target);
          var nh2 = target.countCards("h");
          var num = Math.sqrt(1 + nh2);
          var cardname = _status.event.cardname;
          if (_status.event.du) {
            return 0.5 - att;
          } else if (_status.event.shuimeng) {
            return att / num;
          } else if (cardname == "lebu") {
            return att / num;
          } else if (cardname == "shunshou") {
            if (_status.event.nh <= 2) {
              return att / num;
            }
          } else if (cardname == "huogong") {
            if (_status.event.player.hp == 1) {
              return att / num;
            }
          }
          if (_status.event.nh > nh2 + 1) {
            return att / num;
          }
          return 0;
        },
        du: player.hasCard(function(card) {
          return get.value(card, player, "raw") < 0;
        }),
        shuimeng: (function() {
          if (trigger.card.name == "guohe") {
            return trigger.getParent(2).name == "shuimeng";
          }
          if (trigger.card.name == "wuzhong") {
            return trigger.getParent(3).name == "shuimeng";
          }
        })(),
        nh,
        cardname: trigger.card.name,
        prompt: get.prompt2(event.skill)
      }).forResult();
    },
    async content(event, trigger, player) {
      player.give(event.cards, event.targets[0]);
    }
  },
