  zhenwei: {
    audio: 2,
    audioname: ["re_wenpin"],
    trigger: {
      global: "useCardToTarget"
    },
    direct: true,
    filter(event, player) {
      if (player == event.target || player == event.player) {
        return false;
      }
      if (!player.countCards("he")) {
        return false;
      }
      if (event.targets.length > 1) {
        return false;
      }
      if (!event.target) {
        return false;
      }
      if (event.target.hp >= player.hp) {
        return false;
      }
      var card = event.card;
      if (card.name == "sha") {
        return true;
      }
      if (get.color(card) == "black" && get.type(card, "trick") == "trick") {
        return true;
      }
      return false;
    },
    async content(event, trigger, player) {
      let save = false;
      if (get.attitude(player, trigger.target) > 2) {
        if (trigger.card.name == "sha") {
          if (player.countCards("h", "shan") || player.getEquip(2) || trigger.target.hp == 1 || player.hp > trigger.target.hp + 1) {
            if (!trigger.target.countCards("h", "shan") || trigger.target.countCards("h") < player.countCards("h")) {
              save = true;
            }
          }
        } else if (trigger.card.name == "juedou" && trigger.target.hp == 1) {
          save = true;
        } else if (trigger.card.name == "shunshou" && get.attitude(player, trigger.player) < 0 && get.attitude(trigger.player, trigger.target) < 0) {
          save = true;
        }
      }
      const next = player.chooseToDiscard("he", get.prompt(event.name, trigger.target), "弃置一张牌，将" + get.translation(trigger.card) + "转移给自己，或令此牌对其无效");
      next.logSkill = [event.name, trigger.target];
      next.set("ai", function(card) {
        if (_status.event.aisave) {
          return 7 - get.value(card);
        }
        return 0;
      });
      next.set("aisave", save);
      const result = await next.forResult();
      if (result.bool) {
        const result2 = await player.chooseControl("转移", "失效", function() {
          var trigger2 = _status.event.getTrigger();
          var player2 = _status.event.player;
          if (trigger2.card.name == "sha") {
            if (player2.countCards("h", "shan")) {
              return "转移";
            }
          } else if (trigger2.card.name == "juedou") {
            if (player2.countCards("h", "sha")) {
              return "转移";
            }
          }
          return "失效";
        }).set("prompt", "将" + get.translation(trigger.card) + "转移给你，或令其失效").forResult();
        if (result2.control == "转移") {
          const drawNext = player.draw();
          trigger.getParent().targets.remove(trigger.target);
          trigger.getParent().triggeredTargets2.remove(trigger.target);
          trigger.getParent().targets.push(player);
          trigger.untrigger();
          trigger.player.line(player);
          await drawNext;
          await game.delayx();
        } else {
          const cards2 = trigger.cards.filterInD();
          if (cards2.length > 0) {
            trigger.player.addSkill("zhenwei2");
            const addNext = trigger.player.addToExpansion(cards2, "gain2");
            addNext.gaintag.add("zhenwei2");
            await addNext;
          }
          trigger.targets.length = 0;
          trigger.getParent().triggeredTargets2.length = 0;
        }
      } else {
        event.finish();
        return;
      }
    },
    ai: {
      threaten: 1.1
    }
  },
