  xinfu_chenghao: {
    audio: 2,
    trigger: {
      global: "damageEnd"
    },
    filter(event, player) {
      return event.lianhuanable == true && event.player.isIn();
    },
    frequent: true,
    async content(event, trigger, player) {
      event.cards = game.cardsGotoOrdering(
        get.cards(
          game.countPlayer(function(current) {
            return current.isLinked();
          }) + 1
        )
      ).cards;
      if (_status.connectMode) {
        game.broadcastAll(function() {
          _status.noclearcountdown = true;
        });
      }
      event.given_map = {};
      while (true) {
        let result;
        if (event.cards.length > 1) {
          result = await player.chooseCardButton("称好：请选择要分配的牌", true, event.cards, [1, event.cards.length]).set("ai", function(button) {
            if (ui.selected.buttons.length == 0) {
              return 1;
            }
            return 0;
          }).forResult();
        } else if (event.cards.length == 1) {
          event._result = { links: event.cards.slice(0), bool: true };
          result = event._result;
        } else {
          event.finish();
          return;
        }
        if (result.bool) {
          event.cards.removeArray(result.links);
          event.togive = result.links.slice(0);
          result = await player.chooseTarget("选择一名角色获得" + get.translation(result.links), true).set("ai", function(target) {
            var att = get.attitude(_status.event.player, target);
            if (_status.event.enemy) {
              return -att;
            } else if (att > 0) {
              return att / (1 + target.countCards("h"));
            } else {
              return att / 100;
            }
          }).set("enemy", get.value(event.togive[0], player, "raw") < 0).forResult();
        }
        if (result.targets.length) {
          const id = result.targets[0].playerid, map = event.given_map;
          if (!map[id]) {
            map[id] = [];
          }
          map[id].addArray(event.togive);
        }
        if (event.cards.length <= 0) {
          break;
        }
      }
      if (_status.connectMode) {
        game.broadcastAll(function() {
          delete _status.noclearcountdown;
          game.stopCountChoose();
        });
      }
      const list = [];
      for (const i in event.given_map) {
        const source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
        player.line(source, "green");
        list.push([source, event.given_map[i]]);
      }
      await game.loseAsync({
        gain_list: list,
        giver: player,
        animate: "draw"
      }).setContent("gaincardMultiple");
    }
  },
